entries[10605] = { ["name"] = "Kettenblitzschlag", ["text"] = "605 Mana 30 Meter Reichweite\nWirken in 2.5 sek. 6 sek. Abklingzeit\nSchleudert einen Blitzschlag auf den Gegner, der 505 bis 564 Naturschaden verursacht und auf weitere Gegner in der Nähe überspringt. Jeder Sprung verringert den Schaden um 30% . Wirkt auf insgesamt 3 Ziele." }
