entries[10613] = { ["name"] = "Totem des Windzorns", ["text"] = "175 Mana\nSofort\nTools: Lufttotem\nBeschwört ein Totem des Windzorns mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem verzaubert die Waffenhandwaffen aller Gruppenmitglieder mit Wind, wenn sie sich im Umkreis von 20 Metern aufhalten. Bei jedem Treffer besteht eine Chance von 20%, dass der Angreifer 1 zusätzlichen Angriff mit (229 * 1 ) zusätzlicher Nahkampfangriffskraft erhält. Hält 2 Min. lang an." }
entries[10614] = { ["name"] = "Totem des Windzorns", ["text"] = "250 Mana\nSofort\nTools: Lufttotem\nBeschwört ein Totem des Windzorns mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem verzaubert die Waffenhandwaffen aller Gruppenmitglieder mit Wind, wenn sie sich im Umkreis von 20 Metern aufhalten. Bei jedem Treffer besteht eine Chance von 20%, dass der Angreifer 1 zusätzlichen Angriff mit (315 * 1 ) zusätzlicher Nahkampfangriffskraft erhält. Hält 2 Min. lang an." }
