entries[10619] = { ["name"] = "Drachenschuppenstulpen", ["text"] = "Wirken in 1 min\nReagenzien:\nDickes Leder (24), Abgenutzte Drachenschuppe (12), Schwerer Seidenfaden (4), Geschmeidiger dicker Balg (2)\nDrachenschuppenstulpen\nWird beim Anlegen gebunden\nHände Kette\n171 Rüstung\n+7 Ausdauer\n+6 Willenskraft\nHaltbarkeit 40 / 40\n40\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%." }
