entries[10621] = { ["name"] = "Wolfskopfhelm", ["text"] = "Wirken in 1 min\nReagenzien:\nDickes Leder (18), Dicker Wolfsbalg (2), Tückische Klaue (8), Schwerer Seidenfaden (4), Geschmeidiger dicker Balg (2)\nWolfskopfhelm\nWird beim Anlegen gebunden\nKopf Leder\n109 Rüstung\n+10 Willenskraft\nHaltbarkeit 60 / 60\nKlassen: Druide\n40\nAnlegen: Bei Gestaltwandlung in Katzengestalt erhält der Druide 20 Punkte Energie. Bei Gestaltwandlung in Bärengestalt erhält der Druide 5 Wutpunkte." }
entries[10622] = { ["name"] = "Kettenheilung", ["text"] = "315 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das verbündete Ziel um 419 bis 479 Gesundheit und springt dann weiter, um weitere Ziele in der Nähe zu heilen. Wenn der Zauber auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Nach jedem Sprung beträgt die Heilung 50% des vorhergehenden Wertes. Heilt insgesamt 3 Ziele." }
entries[10623] = { ["name"] = "Kettenheilung", ["text"] = "405 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das verbündete Ziel um 567 bis 646 Gesundheit und springt dann weiter, um weitere Ziele in der Nähe zu heilen. Wenn der Zauber auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Nach jedem Sprung beträgt die Heilung 50% des vorhergehenden Wertes. Heilt insgesamt 3 Ziele." }
