entries[11441] = { ["name"] = "Welkberührung", ["text"] = "Fügt eine Chance hinzu, 'Welkberührung' auf den Gegner zu wirken, wenn der Zaubernde von einem Nahkampfangriff getroffen wird.\n(Procchance: 5%)" }
entries[11442] = { ["name"] = "Welkberührung", ["text"] = "Nahkampfreichweite\nSofort\nLässt einen Feind erkranken, verursacht alle 10 Sek. 2 Punkt(e) Schattenschaden, entzieht alle 10 Sek. 2 Punkt(e) Mana und überträgt sie auf den Zaubernden. Hält 3 Min. lang an." }
