entries[11639] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nMurmelt ein Wort der Dunkelheit, das einem Feind 18 Sek. lang alle 3 Sek. Schattenschaden zufügt." }
entries[11640] = { ["name"] = "Erneuerung", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 15 Sek. lang alle 3 Sek." }
entries[11641] = { ["name"] = "Verhexung", ["text"] = "120 Mana 20 Meter Reichweite\nSofort\nTransformiert einen Feind in einen Frosch, sodass er 10 Sek. lang weder angreifen noch Zauber wirken kann." }
entries[11642] = { ["name"] = "Heilen", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 3.5 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[11643] = { ["name"] = "Goldene Schuppenstulpen", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nStahlbarren (10), Goldbarren (4), Schwerer Schleifstein (4), Citrin\nGoldene Schuppenstulpen\nWird beim Anlegen gebunden\nHände Kette\n146 Rüstung\n+11 Stärke\n+4 Willenskraft\nHaltbarkeit 35 / 35\n36" }
entries[11644] = { ["name"] = "Pläne: Goldene Schuppenstulpen", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch die Herstellung von goldenen Schuppenstulpen." }
