entries[11647] = { ["name"] = "Machtwort: Schild", ["text"] = "100 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nUmgibt den Zaubernden mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und maximal 801 Punkt(e) körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen." }
entries[11649] = { ["name"] = "Unsichtbarkeit entdecken", ["text"] = "90 Mana\nSofort\nErmöglicht dem Spieler, Unsichtbarkeit zu entdecken." }
entries[11650] = { ["name"] = "Kopfnuss", ["text"] = "Nahkampfreichweite\nSofort\nBetäubt ein Ziel 3 Sek. lang." }
entries[11654] = { ["name"] = "Sul'thrazes Ruf", ["text"] = "Wirken in 10 sek.\nReagenzien:\nSang'thraze der Schmetterer\nKombiniert Jang'thraze und Sang'thraze, um das mächtige Schwert Sul'thraze zu bilden." }
entries[11657] = { ["name"] = "Jang'thraze", ["text"] = "Sofort\nSchirmt den Benutzer gegen physischen Schaden ab und absorbiert 55 bis 85 Punkt(e) Schaden. Hält 20 Sek. lang an." }
entries[11658] = { ["name"] = "Sul'thraze", ["text"] = "Nahkampfreichweite\nSofort\nSchlägt einen Feind mit der Wut von Sul'thraze. Verringert die Stärke des Ziels um 15 und fügt 90 bis 210 Punkt(e) Schattenschaden sowie 125 Punkt(e) zusätzlichen Schaden im Verlauf von 15 Sek. zu." }
