entries[11711] = { ["name"] = "Fluch der Pein", ["text"] = "130 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang 504 Punkt(e) Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
